RATES = (200.0, 400.0, 800.0, 1600.0)

def pick_rate(f_max, margin, candidates):
    usable = [c for c in candidates if c >= margin * f_max]
    if not usable:
        return None
    return min(usable)

for f_max, what in ((40.0, "wheel tone"), (120.0, "driver whine"), (500.0, "bearing chirp")):
    print(f"{what:14s} needs {5.0 * f_max:7.1f} Hz and gets {pick_rate(f_max, 5.0, RATES)}")

