import numpy as np

def block_average(x, n):
    usable = x[:x.size - x.size % n]
    return usable.reshape(-1, n).mean(axis=1)

def random_walk(rng, n, step):
    return np.cumsum(step * rng.standard_normal(n))

rng = np.random.default_rng(3)
white = 0.05 * rng.standard_normal(8192)
walk = random_walk(rng, 8192, 0.005)
for n in (1, 4, 16, 64):
    w = float(block_average(white, n).std())
    d = float(block_average(walk, n).std())
    print(f"blocks of {n:3d}  white {w:.5f}  walk {d:.5f}")

import numpy as np

WINDOW = 11

def breakdown_count(size):
    return (size - 1) // 2

