import numpy as np

TAPS = 9

def rms(v):
    return float(np.sqrt(np.mean(v * v)))

def pad_edges(x, pad):
    return np.concatenate([np.full(pad, x[0]), x, np.full(pad, x[-1])])

def smooth(x, weights):
    return np.convolve(pad_edges(x, weights.size // 2), weights, mode="valid")

def median_filter(x, taps):
    padded = pad_edges(x, taps // 2)
    return np.array([np.median(padded[i:i + taps]) for i in range(x.size)])

single = np.ones(TAPS) / TAPS
double = np.convolve(single, single)

def compare(channel, clean):
    scores = {"raw": rms(channel[20:-20] - clean[20:-20])}
    scores["average"] = rms(smooth(channel, single)[20:-20] - clean[20:-20])
    scores["cascade"] = rms(smooth(channel, double)[20:-20] - clean[20:-20])
    scores["median"] = rms(median_filter(channel, TAPS)[20:-20] - clean[20:-20])
    both = smooth(median_filter(channel, TAPS), single)
    scores["median then average"] = rms(both[20:-20] - clean[20:-20])
    return scores

rng = np.random.default_rng(53)
t = np.arange(600) / 200.0
clean = np.sin(2.0 * np.pi * 2.0 * t)
channel = clean + 0.25 * rng.standard_normal(600)
channel[100] = 5.0
channel[250] = -5.0
channel[301] = 5.0
channel[480] = -5.0
for key, v in compare(channel, clean).items():
    print(f"{key:22s} rms error {v:.4f}")

import numpy as np

FS = 1000.0

def amplitudes(x, fs):
    freqs = np.fft.rfftfreq(x.size, 1.0 / fs)
    mag = np.abs(np.fft.rfft(x))
    amp = 2.0 * mag / x.size
    amp[0] = mag[0] / x.size
    return freqs, amp

def find_peaks(freqs, amp, floor):
    hits = []
    for i in range(1, amp.size - 1):
        if amp[i] > floor and amp[i] >= amp[i - 1] and amp[i] > amp[i + 1]:
            hits.append((float(freqs[i]), float(amp[i])))
    return sorted(hits, key=lambda h: -h[1])

t = np.arange(2000) / FS
channel = (2.5 + 0.4 * np.sin(2.0 * np.pi * 37.0 * t) + 0.9 * np.sin(2.0 * np.pi * 137.0 * t)
           + 0.12 * np.sin(2.0 * np.pi * 274.0 * t))
freqs, amp = amplitudes(channel, FS)
for f, a in find_peaks(freqs, amp, 0.05):
    print(f"{f:7.2f} Hz  amplitude {a:.4f}")

import numpy as np

FS = 200.0

def zero_pad(x, factor):
    return np.concatenate([x, np.zeros(x.size * (factor - 1))])

def peak_frequency(x, fs):
    freqs = np.fft.rfftfreq(x.size, 1.0 / fs)
    mag = np.abs(np.fft.rfft(x))
    return float(freqs[int(np.argmax(mag))]), float(freqs[1] - freqs[0])

