import numpy as np

FS = 1000.0

def detrend(x):
    idx = np.arange(x.size)
    slope, offset = np.polyfit(idx, x, 1)
    return x - (slope * idx + offset)

def find_peaks(freqs, amp, floor):
    hits = []
    for i in range(1, amp.size - 1):
        if amp[i] > floor and amp[i] >= amp[i - 1] and amp[i] > amp[i + 1]:
            hits.append((float(freqs[i]), float(amp[i])))
    return sorted(hits, key=lambda h: -h[1])

def analyse(x, fs, floor):
    freqs = np.fft.rfftfreq(x.size, 1.0 / fs)
    flat = detrend(x)
    mag = np.abs(np.fft.rfft(flat))
    amp = 2.0 * mag / x.size
    amp[0] = mag[0] / x.size
    return freqs, amp, find_peaks(freqs, amp, floor)

rng = np.random.default_rng(71)
t = np.arange(4000) / FS
channel = (1.8 + 0.3 * t + 0.50 * np.sin(2.0 * np.pi * 24.0 * t)
           + 0.22 * np.sin(2.0 * np.pi * 96.0 * t) + 0.07 * np.sin(2.0 * np.pi * 288.0 * t)
           + 0.01 * rng.standard_normal(4000))
freqs, amp, peaks = analyse(channel, FS, 0.03)
print(f"{freqs.size} bins searched, {len(peaks)} peaks above the floor")
for f, a in peaks:
    print(f"{f:7.2f} Hz  amplitude {a:.4f}")

import numpy as np

FS = 200.0

def amplitudes(x, fs):
    freqs = np.fft.rfftfreq(x.size, 1.0 / fs)
    mag = np.abs(np.fft.rfft(x))
    amp = 2.0 * mag / x.size
    amp[0] = mag[0] / x.size
    return freqs, amp

def hann_window(n):
    return 0.5 - 0.5 * np.cos(2.0 * np.pi * np.arange(n) / (n - 1))

def coherent_gain(w):
    return float(w.mean())

def correct_amplitude(amp, w):
    return amp / coherent_gain(w)

t = np.arange(200) / FS
w = hann_window(200)
print(f"coherent gain {coherent_gain(w):.4f}")
for f0 in (20.0, 20.5):
    freqs, amp = amplitudes(np.sin(2.0 * np.pi * f0 * t) * w, FS)
    fixed = correct_amplitude(amp, w)
    print(f"{f0:5.1f} Hz  raw {amp.max():.4f}  corrected {fixed.max():.4f}")

