import numpy as np

FS = 1000.0

def sinc_taps(fc, fs, taps):
    k = np.arange(taps)
    m = (taps - 1) / 2.0
    return 2.0 * fc / fs * np.sinc(2.0 * fc * (k - m) / fs)

def hann_window(n):
    return 0.5 - 0.5 * np.cos(2.0 * np.pi * np.arange(n) / (n - 1))

def response(h, f, fs):
    k = np.arange(h.size)
    z = np.exp(-2j * np.pi * f * k / fs)
    return float(abs(np.sum(h * z)))

def windowed_taps(fc, fs, taps):
    # TODO: fade the ends of the ideal response away
    return sinc_taps(fc, fs, taps)

for label, h in (("truncated", sinc_taps(100.0, FS, 51)), ("windowed", windowed_taps(100.0, FS, 51))):
    h = h / h.sum()
    pass_band = [response(h, f, FS) for f in np.linspace(0.0, 60.0, 400)]
    stop_band = [response(h, f, FS) for f in np.linspace(150.0, 499.0, 800)]
    print(f"{label:10s} passband {min(pass_band):.4f} to {max(pass_band):.4f}   stopband {20.0 * np.log10(max(stop_band)):7.2f} dB")

