def iir_response(b, a, f, fs):
    w = 2.0 * np.pi * f / fs
    num = np.sum(b * np.exp(-1j * w * np.arange(b.size)))
    den = np.sum(a * np.exp(-1j * w * np.arange(a.size)))
    return float(abs(num / den))

def notch(f0, fs, r):
    w0 = 2.0 * np.pi * f0 / fs
    b = np.array([1.0, -2.0 * np.cos(w0), 1.0])
    a = np.array([1.0, -2.0 * r * np.cos(w0), r * r])
    return b / iir_response(b, a, 0.0, fs), a

def iir_filter(x, b, a):
    y = np.zeros(x.size)
    for n in range(x.size):
        acc = b[0] * x[n]
